style.css:
@-moz-document domain("instagram.com") {
:root {
    color-scheme: light;
    --mc-bg: #fff0f8;
    --mc-pink: #ffb6dc;
    --mc-hot: #ff1493;
    --mc-neon: #ff48b9;
    --mc-dark: #a30b60;
    --mc-border: #ff82c5;
    --mc-white: #fffafd;
  }

  html,
  body {
    background-color: var(--mc-bg) !important;
    color: var(--mc-dark) !important;
  }

 
/* ? MC BLING: FONDO ROSA LEOPARDO */

html,
body {
  background: #ffc6e5 !important;
  background-color: #ffc6e5 !important;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;

  background-color: #ffc6e5;
  background-image:
    radial-gradient(
      ellipse at 30% 40%,
      transparent 0 20%,
      #b51b65 22% 30%,
      #ff75bf 33% 48%,
      transparent 51%
    ),
    radial-gradient(
      ellipse at 70% 65%,
      transparent 0 18%,
      #b51b65 22% 31%,
      #ff75bf 34% 48%,
      transparent 51%
    );

  background-size: 90px 80px;
  opacity: 0.45;
}

/* Mantiene la interfaz por encima del estampado */
body > * {
  position: relative;
}

/* Superficies principales rosadas */
main,
[role="main"] {
  background-color: #fff0f8 !important;
}
  
  /* ? Navegación */
  nav,
  header,
  [role="navigation"] {
    border-color: var(--mc-border) !important;
  }

  nav a:hover,
  nav button:hover,
  [role="navigation"] a:hover,
  [role="navigation"] button:hover {
    background-color: #ffb6dc88 !important;
    color: var(--mc-hot) !important;
  }

  /* ? Botones */
  button,
  [role="button"] {
    border-color: var(--mc-border) !important;
    transition: all 0.2s ease !important;
  }

  button[type="submit"] {
    background: linear-gradient(
      135deg,
      #ff8bce,
      #ff1493 55%,
      #d60079
    ) !important;
    color: white !important;
    border-radius: 14px !important;
    box-shadow:
      0 0 5px #ff69b4aa,
      0 0 14px #ff149355 !important;
  }

  button:hover,
  [role="button"]:hover {
    filter: saturate(1.2);
    box-shadow: 0 0 12px #ff69b477 !important;
  }

  /* ? Búsqueda, comentarios y mensajes */
  input,
  textarea,
  [contenteditable="true"] {
    background-color: #fff8fc !important;
    color: #64113f !important;
    border: 1px solid var(--mc-border) !important;
    border-radius: 12px !important;
    caret-color: var(--mc-hot) !important;
  }

  input:focus,
  textarea:focus,
  [contenteditable="true"]:focus {
    outline: 2px solid var(--mc-hot) !important;
    box-shadow: 0 0 12px #ff69b477 !important;
  }

  /* ? Ventanas y menús */
  [role="dialog"],
  [role="menu"],
  [role="listbox"] {
    background-color: #fff4fa !important;
    color: var(--mc-dark) !important;
    border: 1px solid var(--mc-border) !important;
    border-radius: 18px !important;
    box-shadow: 0 8px 30px #b8328050 !important;
  }

  [role="menuitem"]:hover,
  [role="option"]:hover {
    background-color: #ffd1eb !important;
    color: var(--mc-hot) !important;
  }

  /* ? Enlaces */
  a:hover {
    color: var(--mc-hot) !important;
  }

  ::selection {
    background: var(--mc-hot) !important;
    color: white !important;
  }

  /* ? Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #fff0f8;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      #ffc6e5,
      #ff1493,
      #c21876
    );
    border: 2px solid #fff0f8;
    border-radius: 20px;
  }
}
